INSERT INTO "Task" (id, title, description, status, priority, "dueDate", "scheduledDate", "scheduledTime", "recurrenceType", "completedAt", "calendarId", "createdById", "sortOrder", "createdAt", "updatedAt") VALUES ('cm0a28b81377304f4daae0abe', '전세집 관련 부동산 문의', '안녕하세요. 잘지내셨나요?
2111동 1302호 세입자 이현규입니다.
이번에 임대인께서 아파트 매매하시려는 것으로 알고 있는데요.
관련해서 몇가지 문의 드리고자 합니다.

먼저, 집 컨디션 및 수리와 관련된 건입니다.
저희가 이사 온 시점에 파손 되어있었거나, 수리가 필요한 소요들이 있습니다.
당장 지내는 것이 문제 되지는 않고, 언제든 수리 요청 하시라고 하셔서 문제가 될 때쯤 말씀드리려고 했었는데요.
매매 의사가 있으시면, 현 임대인분도, 매입을 하시려는 분께도 곤란스러운 일인 것 같아서요.
이런 경우에는 어떻게 처리하는게 좋을까요?
또, 당장 수리를 하지 않더라도, 저희가 파손한 것이 아니라 원래부터 파손되어 있었던 것들에 대해서 확인시켜드리거나 해야할까요?

다음은 계약과 관련된 건입니다.
매입하시는 분께서 전세를 고려중이라고 하셨는데, 그러면 매매 이후에 전세 계약을 다시 체결하는 형태가 될까요?
매입하시는 분의 의사에 따라서 전세 계약이 이뤄지지 않을수도 있을까요?
추가로, 전세 보증과 관련된 내용은 계약 이후에 저희가 따로 신청드리면 되는 것인지 궁금합니다.', 'DONE', 'NONE', '2025-11-03T15:00:00+00:00', '2025-11-03T15:00:00+00:00', NULL, 'NONE', '2025-11-04T05:06:40+00:00', 'cm9e8c2b60da474ba1af50729', 'cmtu2p0so001eyz4f7moqr85g', 0, '2025-11-03T01:08:49+00:00', '2025-11-03T01:08:49+00:00');
