INSERT INTO "Task" (id, title, description, status, priority, "dueDate", "scheduledDate", "scheduledTime", "recurrenceType", "completedAt", "calendarId", "createdById", "sortOrder", "createdAt", "updatedAt") VALUES ('cm861b10699c62401599de7a9', 'Daily record', '거의 하루종일 아무것도 안하고 누워있던 것 같음.
옷 차려입고 나감. 케이원가서 저녁 먹고 집에 옴.
잠깐 자리 앉아서, 해야할 일 정리 정도 함.
