INSERT INTO "Task" (id, title, description, status, priority, "dueDate", "scheduledDate", "scheduledTime", "recurrenceType", "completedAt", "calendarId", "createdById", "sortOrder", "createdAt", "updatedAt") VALUES ('cm5e02a2d2306c4642b6e5be5', 'Daily record', '오늘도 업무시간엔 계속 누워있었다. (예은이는 DRX랑 EDG 경기 보면서 신나했다.)
몸 상태가 나쁜건 아니었는데, 근래 계속 이 시간에 누워있었어서 그런지 뭔가 집중할만한 에너지도 없었다.
두 번의 싱크업때만 겨우 일어나서 참여했었고, 5시쯤에도 겨우 일어나서 병원에 갔다.
의외로 알러지 검사 결과는, 있던 먼지 알러지도 없어졌고 완전 깔끔했다.
눈이 계속 간지러운 이유는 잘 모르겠지만, 아무튼 결과는 좋았다.
검진 이후에는 운동을 하러 갔다. 일주일동안 앓았더니 2.5kg정도 빠졌었고, 뭔가 전보다 힘이 있지는 않았다.
그래도, 허리 안아프게 데드도 할 수 있었고, 여러모로 꽤 재밌게 운동을 했다.
집에 와서는 점심에 남긴 돈가스 등으로 저녁 대충 먹고, 이런 저런 일을 정리했다. (이주비 관련, 인규 컴퓨터 관련 등)
정리도 좀 됐겠다. 다시 열심히 살 시간이 온 것 같다.', 'DONE', 'NONE', '2022-10-24T14:30:00+00:00', '2022-10-24T14:30:00+00:00', '23:30', 'NONE', '2022-10-24T13:32:38+00:00', 'cm9e8c2b60da474ba1af50729', 'cmtu2p0so001eyz4f7moqr85g', 0, '2022-08-23T14:41:58+00:00', '2022-08-23T14:41:58+00:00');
