INSERT INTO "Task" (id, title, description, status, priority, "dueDate", "scheduledDate", "scheduledTime", "recurrenceType", "completedAt", "calendarId", "createdById", "sortOrder", "createdAt", "updatedAt") VALUES ('cm0095685adcb841cd8180384', 'Daily record', '늦게 일어났고, 그래도 움직이긴 해야할 거 같아서, 예은이랑 나가기로 했다.
예은이가 전부터 같이 가자고 했던 "롤리폴리 꼬또" 라는 곳에 가서 저녁을 먹었다.
