INSERT INTO "Task" (id, title, description, status, priority, "dueDate", "scheduledDate", "scheduledTime", "recurrenceType", "completedAt", "calendarId", "createdById", "sortOrder", "createdAt", "updatedAt") VALUES ('cme64aa5baf58f47bb83f1430', 'Daily record', '늦게까지 정신 못차리고 술마시다가, 꼬멜네서 잤다.
8시쯤 아무튼 일어는 났고, 회사를 가야하나 말아야하나 무수히 고민을 했다.
가봤자 할 일도 못해놨고, 오히려 술냄새 풍기면서 정신 못차리는 모습 보이는 것보다는, 쉬고 오후에 일하는게 낫겠다 싶었다.
요전에도 써먹었던 알러지 핑계로 PST를 사용하고, 꼬멜네서 늘어지게 잤다.
아침에 괜히 속 좀 정리하겠다고 숙취 음료 마셨다가, 그거 때문에 토하고 하루종일 상태가 메롱했다.
오후에 꼬멜 서류작업 하는 거 좀 도와주다가 헤어졌다.
뭐 식사하고 버스타려는데, 이곳저곳에서 브레이크 타임 등으로 까이고, 모기가 잔뜩있는 콩나물 국밥 집에서 겨우 식사를 했다.
버스타고 집에 와서도, 업무가 너무너무 하기 싫어서 미루고 미루면서 누워있었다.
저녁에도 라면 끓여먹고, 예은이랑 산책 좀 하고 그냥 자버렸다.', 'DONE', 'NONE', '2022-10-04T14:30:00+00:00', '2022-10-04T14:30:00+00:00', '23:30', 'NONE', '2022-10-05T13:14:13+00:00', 'cm9e8c2b60da474ba1af50729', 'cmtu2p0so001eyz4f7moqr85g', 0, '2022-10-05T13:13:42+00:00', '2022-10-05T13:13:42+00:00');
