INSERT INTO "Task" (id, title, description, status, priority, "dueDate", "scheduledDate", "scheduledTime", "recurrenceType", "completedAt", "calendarId", "createdById", "sortOrder", "createdAt", "updatedAt") VALUES ('cmfe7245dd6e1a457b8f509c6', 'Daily record', '그래도 이미지 파이프라인 코드리뷰까지 받음.
업무 잘 하고, 저녁에 팀원들이랑 회식함.
형주님이랑 얘기 잘 하고 놈.
