INSERT INTO "Task" (id, title, description, status, priority, "dueDate", "scheduledDate", "scheduledTime", "recurrenceType", "completedAt", "calendarId", "createdById", "sortOrder", "createdAt", "updatedAt") VALUES ('cm560ff94dadbe4e1d86e0236', 'Daily record', '고베에서 아리마온센으로 이동
아침 일찍 일어나서 고베 구경함.
키타노로 넘어가서 거리의 이진칸 구경함.
세상에서 제일 아름답다는 스타벅스도 가고, 이래저래 사진찍으면서 놈.
따듯한데서 쉬다가, 고베 시내쪽으로 이동해서 점심 식사 찾음.
나름 유명한 스테이크하우스?에 운좋게 거의 안기다리고 들어감. 고베규 등 철판 구이로 점심식사 함.
기분좋게 나와서 고베 시내 이곳저곳 구경하고 버스 터미널로 감.
버스타니 금방 아리마온센 도착함.
네기야 료칸에 도착해서 짐 풀고 료칸 구경함.
이후 근처 동네 구경하러 나옴. 여기저기 구경하는데, 이렇다할 멋진 건 없어도 주변 경치가 좋았음.
또 족욕할 수 있게 된 곳이 있어서 양말벗고 즐김.
이래저래 돌다가 료칸으로 돌아왔고, 대욕장에서 온천 즐김.
저녁으로는 가이세키를 먹었는데, 둘 모두한테 굉장히 도전적인 음식들이었음.
식사하고 잠깐 잤다가, 새벽 2시쯤 일어남.
일어나니 눈이 좀 오고 있었음. 프라이빗 온천에서 눈보면서 온천 즐기다가 나옴.', 'DONE', 'NONE', '2022-12-22T14:30:00+00:00', '2022-12-22T14:30:00+00:00', '23:30', 'NONE', '2022-12-25T03:07:45+00:00', 'cm9e8c2b60da474ba1af50729', 'cmtu2p0so001eyz4f7moqr85g', 0, '2022-08-23T14:41:58+00:00', '2022-08-23T14:41:58+00:00');
