INSERT INTO "Task" (id, title, description, status, priority, "dueDate", "scheduledDate", "scheduledTime", "recurrenceType", "completedAt", "calendarId", "createdById", "sortOrder", "createdAt", "updatedAt") VALUES ('cm87feebaa6aff401d95997d3', 'Daily record', '아침에 너무너무 일어나기 싫어서 늑장부리다가 꽤나 늦게 출근했다. 출근해서도 업무가 생각보다 잘 진전되지 않았고, 여러모로 진행이 잘 안됐다.
심지어 너무너무 졸려서, 잠깐 회의실에 들어가서 눈도 붙였다. 저녁 늦게까지 작업하려고 했는데, 그마저도 잘 안돼서 집으로 왔다.
집에 와서는 일찍 잠들었고 12시쯤 일어났다.
식사 대충 하고, 앉아서 바로 업무 시작했어야 했는데, 조금 쉰다는게 결국 화근이 됐다.
결국 자리에는 앉지도 못하고 그렇게 제대로 쉬지도, 일하지도 못한 채 날이 밝았다.', 'DONE', 'NONE', '2023-01-03T14:30:00+00:00', '2023-01-03T14:30:00+00:00', '23:30', 'NONE', '2023-01-03T14:58:38+00:00', 'cm9e8c2b60da474ba1af50729', 'cmtu2p0so001eyz4f7moqr85g', 0, '2022-08-23T14:41:58+00:00', '2022-08-23T14:41:58+00:00');
