INSERT INTO "Task" (id, title, description, status, priority, "dueDate", "scheduledDate", "scheduledTime", "recurrenceType", "completedAt", "calendarId", "createdById", "sortOrder", "createdAt", "updatedAt") VALUES ('cma0787ad5a35744b7b119472', 'Daily record', '새벽에 할머니 돌아가셨다는 소식 들음.
부트캠프 마지막인 만큼 같이 마무리하고 싶어서 출근함.
업무 마무리 하고 집으로 옴.
인규랑 연락해서 데리고 장례식장으로 감.', 'DONE', 'NONE', '2023-01-19T14:30:00+00:00', '2023-01-19T14:30:00+00:00', '23:30', 'NONE', '2023-01-20T03:54:35+00:00', 'cm9e8c2b60da474ba1af50729', 'cmtu2p0so001eyz4f7moqr85g', 0, '2022-08-23T14:41:58+00:00', '2022-08-23T14:41:58+00:00');
INSERT INTO "Task" (id, title, description, status, priority, "dueDate", "scheduledDate", "scheduledTime", "recurrenceType", "completedAt", "calendarId", "createdById", "sortOrder", "createdAt", "updatedAt") VALUES ('cme188966984f24b9788328f8', 'Daily record', '장례식장에서 자고, 일어나서 계속 장례 일 봄.
엄마랑 예은이 왔다가 감.', 'DONE', 'NONE', '2023-01-20T14:30:00+00:00', '2023-01-20T14:30:00+00:00', '23:30', 'NONE', '2023-01-21T05:52:17+00:00', 'cm9e8c2b60da474ba1af50729', 'cmtu2p0so001eyz4f7moqr85g', 0, '2022-08-23T14:41:58+00:00', '2022-08-23T14:41:58+00:00');
INSERT INTO "Task" (id, title, description, status, priority, "dueDate", "scheduledDate", "scheduledTime", "recurrenceType", "completedAt", "calendarId", "createdById", "sortOrder", "createdAt", "updatedAt") VALUES ('cm9dbd353eafc54646905e2c6', 'Daily record', '발인하고나서, 할머니 현충원에 안장시켜드림.
수원 갔다가, 인규 데리고, 주암동으로 옴.
저녁에 치킨 먹고 잠.', 'DONE', 'NONE', '2023-01-21T14:30:00+00:00', '2023-01-21T14:30:00+00:00', '23:30', 'NONE', '2023-01-24T14:35:41+00:00', 'cm9e8c2b60da474ba1af50729', 'cmtu2p0so001eyz4f7moqr85g', 0, '2022-08-23T14:41:58+00:00', '2022-08-23T14:41:58+00:00');
INSERT INTO "Task" (id, title, description, status, priority, "dueDate", "scheduledDate", "scheduledTime", "recurrenceType", "completedAt", "calendarId", "createdById", "sortOrder", "createdAt", "updatedAt") VALUES ('cmeb2604f47376446eb95c42b', 'Daily record', '10시쯤 가기 싫은 몸 이끌고 겨우 수원 집에 감.
다같이 나름 즐겁게 술 마시고, 다행히도 싸움 안나고 잘 마무리 됨.
아빠는 무슨 주암동 집 파는거 부터해서, 결혼식에 엄마 오는 것 등 여러모로 마음에 안드는 얘기를 계속함.
저녁에 잠깐 자고 인규 데리고 나옴.
집 도착했는데, 속이 안좋아서 토하고, 그때부터 아프기 시작함.
잠을 자고 일어나도 계속 속 안좋고, 위액만 한 10번은 토함.', 'DONE', 'NONE', '2023-01-22T14:30:00+00:00', '2023-01-22T14:30:00+00:00', '23:30', 'NONE', '2023-01-24T14:35:51+00:00', 'cm9e8c2b60da474ba1af50729', 'cmtu2p0so001eyz4f7moqr85g', 0, '2022-08-23T14:41:58+00:00', '2022-08-23T14:41:58+00:00');
INSERT INTO "Task" (id, title, description, status, priority, "dueDate", "scheduledDate", "scheduledTime", "recurrenceType", "completedAt", "calendarId", "createdById", "sortOrder", "createdAt", "updatedAt") VALUES ('cma73a4435f30b44c19f0f47a', 'Daily record', '하루종일 계속 술병으로 고생함.
막판에 타이레놀 먹고 겨우 잠들었음.
하루 쌩으로 잠만 자면서 보냄.', 'DONE', 'NONE', '2023-01-23T14:30:00+00:00', '2023-01-23T14:30:00+00:00', '23:30', 'NONE', '2023-01-24T14:35:58+00:00', 'cm9e8c2b60da474ba1af50729', 'cmtu2p0so001eyz4f7moqr85g', 0, '2022-08-23T14:41:58+00:00', '2022-08-23T14:41:58+00:00');
INSERT INTO "Task" (id, title, description, status, priority, "dueDate", "scheduledDate", "scheduledTime", "recurrenceType", "completedAt", "calendarId", "createdById", "sortOrder", "createdAt", "updatedAt") VALUES ('cm62943b101087445cb9973b9', 'Daily record', '아침에 겨우 정신차림.
예은이랑 6주년 기념으로 점심식사 하러 나옴.
식사하고나서, 신대방 집으로 감.
보일러 한번 돌리고, 좀 쉬다가 집으로 옴.
운동 다녀와서, 집 정리함.
예은이 자는 동안 엄마랑 통화하고, 그간 있었던 일 얘기함.
엄마한테 이것저것 말하고 나니 그래도 머리가 좀 정리됨.
새벽까지 이것저것 정리하다가 늦게 잠.', 'DONE', 'NONE', '2023-01-24T14:30:00+00:00', '2023-01-24T14:30:00+00:00', '23:30', 'NONE', '2023-01-24T14:35:59+00:00', 'cm9e8c2b60da474ba1af50729', 'cmtu2p0so001eyz4f7moqr85g', 0, '2022-08-23T14:41:58+00:00', '2022-08-23T14:41:58+00:00');
